1	// Package cmdsuggest renders the command-suggestion list shown under the
2	// command line (DEVDESK-89). Rendering is pure: state in, lines out.
3	package cmdsuggest
4	
5	import (
6		"fmt"
7		"strings"
8	
9		"github.com/charmbracelet/lipgloss"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// MaxVisibleRows is the ceiling on suggestion rows shown at once.
17	const MaxVisibleRows = 8
18	
19	// Row is one suggestion; Current marks the view that is open now.
20	type Row struct {
21		Entry   command.Entry
22		Current bool
23	}
24	
25	// Frame selects the corners of the bottom rule.
26	type Frame int
27	
28	const (
29		// FrameJoined draws ├─┤ (the list sits above more viewport content).
30		FrameJoined Frame = iota
31		// FrameClosed draws └─┘.
32		FrameClosed
33	)
34	
35	// Input is everything Render needs.
36	type Input struct {
37		Rows    []Row
38		Total   int
39		Query   string
40		Cursor  int // -1 means no highlighted row
41		Offset  int
42		Notice  string
43		Width   int
44		Visible int
45		Frame   Frame
46	}
47	
48	// Layout holds column widths in cells.
49	type Layout struct{ Marker, Name, Alias, Desc int }
50	
51	// Pair is a foreground/background combination the list paints.
52	type Pair struct {
53		Name   string
54		Fg, Bg lipgloss.Color
55	}
56	
57	// Layout constants, in cells. The widths below are the whole grid: a line is
58	// a border, a one-cell margin, the columns, then fill up to the other border.
59	const (
60		margin        = 1
61		markerWidth   = 2
62		minDescWidth  = 20
63		minAliasWidth = 34 // narrowest terminal that still shows the alias column
64		wideWidth     = 100
65		aliasSep      = " · "
66		currentTag    = "(current)"
67		ellipsis      = "…"
68	)
69	
70	// VisibleRows returns how many list rows fit: the matches, at least one row
71	// (the "no match" line), capped by MaxVisibleRows and by the usable height
72	// minus the filet.
73	func VisibleRows(matches, usable int) int {
74		return max(min(max(matches, 1), MaxVisibleRows, usable-1), 0)
75	}
76	
77	// Window returns the first visible row so that cursor stays in view. The
78	// window never wraps and, with no highlighted row, keeps the current offset.
79	func Window(cursor, offset, visible int) int {
80		offset = max(offset, 0)
81		if cursor < 0 || visible <= 0 {
82			return offset
83		}
84		switch {
85		case cursor < offset:
86			return cursor
87		case cursor >= offset+visible:
88			return cursor - visible + 1
89		}
90		return offset
91	}
92	
93	// Columns returns the column widths for a terminal width. Columns leave from
94	// the right: description first, then alias; the name alone remains.
95	func Columns(width int) Layout {
96		l := Layout{Marker: markerWidth}
97		if width < minAliasWidth {
98			l.Name = max(width-6, 1)
99			return l
100		}
101		l.Name, l.Alias = 15, 14
102		if width >= wideWidth {
103			l.Name, l.Alias = 18, 18
104		}
105		if desc := width - 2 - margin - l.Marker - l.Name - l.Alias; desc >= minDescWidth {
106			l.Desc = desc
107		}
108		return l
109	}
110	
111	// first returns the index of the first row drawn, kept inside the list.
112	func first(in Input) int {
113		return max(min(in.Offset, len(in.Rows)-in.Visible), 0)
114	}
115	
116	// FiletLabel returns the text of the bottom rule: the notice as a warning
117	// when there is one, otherwise the count with what scrolled out of view.
118	func FiletLabel(in Input) string {
119		if in.Notice != "" {
120			return theme.IconWarning + " " + in.Notice
121		}
122		label := fmt.Sprintf("%d of %d", len(in.Rows), in.Total)
123		if strings.TrimSpace(in.Query) == "" {
124			label = fmt.Sprintf("%d available", len(in.Rows))
125		}
126		start := first(in)
127		if above := start; above > 0 {
128			label += fmt.Sprintf(" · ▲ %d more", above)
129		}
130		if below := len(in.Rows) - start - in.Visible; below > 0 {
131			label += fmt.Sprintf(" · ▼ %d more", below)
132		}
133		return label
134	}
135	
136	// look is one foreground/background combination, read from the theme at call
137	// time so that a theme applied after start-up is honored.
138	type look struct {
139		name string
140		fg   lipgloss.Color
141		bg   lipgloss.Color
142		bold bool
143	}
144	
145	func (k look) style() lipgloss.Style {
146		return lipgloss.NewStyle().Foreground(k.fg).Background(k.bg).Bold(k.bold)
147	}
148	
149	func rowLook() look {
150		return look{name: "row", fg: theme.ColorText, bg: theme.ColorBackground}
151	}
152	
153	func highlightLook() look {
154		return look{name: "highlighted row", fg: theme.ColorText, bg: theme.ColorTableLineSelected, bold: true}
155	}
156	
157	func filetLook() look {
158		return look{name: "filet label", fg: theme.ColorText, bg: theme.ColorBackground}
159	}
160	
161	func warningLook() look {
162		return look{name: "filet warning", fg: theme.ColorFooterWarn, bg: theme.ColorBackground, bold: true}
163	}
164	
165	// Palette lists every text pair the list paints, for the contrast test. The
166	// frame characters are decoration and carry no information, so they are not
167	// listed.
168	func Palette() []Pair {
169		var out []Pair
170		for _, k := range []look{rowLook(), highlightLook(), filetLook(), warningLook()} {
171			out = append(out, Pair{Name: k.name, Fg: k.fg, Bg: k.bg})
172		}
173		return out
174	}
175	
176	// Render returns Visible list rows followed by the bottom rule, each exactly
177	// Width cells wide. Every line is assembled from separately styled segments;
178	// no already-styled text is ever cut.
179	func Render(in Input) []string {
180		inner := max(in.Width-2, 0)
181		layout := Columns(in.Width)
182		border := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
183		side := border.Render("│")
184	
185		lines := make([]string, 0, in.Visible+1)
186		if len(in.Rows) == 0 {
187			lines = append(lines, side+row(noMatchText(in.Query), layout, inner, false)+side)
188			for i := 1; i < in.Visible; i++ {
189				lines = append(lines, side+theme.EmptyLineBg(inner)+side)
190			}
191		} else {
192			start := first(in)
193			for i := 0; i < in.Visible; i++ {
194				idx := start + i
195				if idx >= len(in.Rows) {
196					lines = append(lines, side+theme.EmptyLineBg(inner)+side)
197					continue
198				}
199				lines = append(lines, side+row(columnsOf(in.Rows[idx], layout), layout, inner, idx == in.Cursor)+side)
200			}
201		}
202		return append(lines, filet(in, inner, border))
203	}
204	
205	// cells is the plain text of each column of one row.
206	// A message spans every column.
207	type cells struct{ name, alias, desc, message string }
208	
209	func noMatchText(query string) cells {
210		return cells{message: fmt.Sprintf("No match for %q", query)}
211	}
212	
213	// columnsOf returns the plain text of a row for a layout. The current marker
214	// leads the description, or stands in for the aliases when the description
215	// is hidden; it is dropped when neither column exists.
216	func columnsOf(r Row, l Layout) cells {
217		c := cells{
218			name:  r.Entry.Label(),
219			alias: strings.Join(r.Entry.Aliases, aliasSep),
220			desc:  r.Entry.Description,
221		}
222		if r.Current {
223			switch {
224			case l.Desc > 0:
225				c.desc = strings.TrimSpace(currentTag + " " + c.desc)
226			case l.Alias > 0:
227				c.alias = currentTag
228			}
229		}
230		return c
231	}
232	
233	// fit truncates plain text to leave one cell of air inside its column and
234	// pads it to the full width.
235	func fit(text string, width int) string {
236		if width <= 0 {
237			return ""
238		}
239		if lipgloss.Width(text) > width-1 {
240			text = ansi.Truncate(text, max(width-1, 1), ellipsis)
241		}
242		return text + strings.Repeat(" ", max(width-lipgloss.Width(text), 0))
243	}
244	
245	// row assembles one list line from styled segments, filled up to inner cells.
246	// A highlighted row fills with its own background so it reaches the border.
247	func row(c cells, l Layout, inner int, highlighted bool) string {
248		k, marker := rowLook(), strings.Repeat(" ", markerWidth)
249		if highlighted {
250			k, marker = highlightLook(), theme.IconCircleSmall+" "
251		}
252		st := k.style()
253		body := fit(c.name, l.Name) + fit(c.alias, l.Alias) + fit(c.desc, l.Desc)
254		if c.message != "" {
255			body = fit(c.message, max(inner-margin-markerWidth, 0))
256		}
257		plain := strings.Repeat(" ", margin) + marker + body
258		if w := lipgloss.Width(plain); w < inner {
259			plain += strings.Repeat(" ", inner-w)
260		}
261		return st.Render(plain)
262	}
263	
264	// filet builds the bottom rule with its label.
265	func filet(in Input, inner int, border lipgloss.Style) string {
266		left, right := "├", "┤"
267		if in.Frame == FrameClosed {
268			left, right = "└", "┘"
269		}
270		k := filetLook()
271		if in.Notice != "" {
272			k = warningLook()
273		}
274		label := ansi.Truncate(FiletLabel(in), max(inner-3, 0), ellipsis)
275		dashes := max(inner-2-lipgloss.Width(label)-1, 0)
276		return border.Render(left+"─ ") + k.style().Render(label) +
277			border.Render(" "+strings.Repeat("─", dashes)+right)
278	}
