1	package cmdsuggest
2	
3	import (
4		"strings"
5		"testing"
6	
7		"github.com/charmbracelet/lipgloss"
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/command"
11		"github.com/anthnel/devdesk/internal/ui/testutil"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	func allRows() []Row {
16		var rows []Row
17		for _, e := range command.Entries() {
18			rows = append(rows, Row{Entry: e})
19		}
20		return rows
21	}
22	
23	func plain(lines []string) []string {
24		out := make([]string, len(lines))
25		for i, l := range lines {
26			out[i] = ansi.Strip(l)
27		}
28		return out
29	}
30	
31	// render fails the test instead of panicking when the line count is wrong.
32	func render(t *testing.T, in Input) []string {
33		t.Helper()
34		lines := Render(in)
35		if len(lines) != in.Visible+1 {
36			t.Fatalf("Render returned %d lines, want %d", len(lines), in.Visible+1)
37		}
38		return lines
39	}
40	
41	func base(width int) Input {
42		rows := allRows()
43		return Input{Rows: rows, Total: len(rows), Cursor: -1, Width: width, Visible: 4}
44	}
45	
46	func TestRegistryHasSeventeenEntries(t *testing.T) {
47		if n := len(command.Entries()); n != 17 {
48			t.Fatalf("fixture assumes 17 entries, registry has %d", n)
49		}
50	}
51	
52	func TestVisibleRows(t *testing.T) {
53		tests := []struct{ matches, usable, want int }{
54			{5, 0, 0}, {5, 1, 0}, {5, 2, 1}, {5, 9, 5}, {17, 9, 8},
55			{17, 30, 8}, {0, 9, 1}, {0, 2, 1}, {3, 3, 2},
56		}
57		for _, tt := range tests {
58			if got := VisibleRows(tt.matches, tt.usable); got != tt.want {
59				t.Errorf("VisibleRows(%d,%d) = %d, want %d", tt.matches, tt.usable, got, tt.want)
60			}
61		}
62	}
63	
64	func TestWindow(t *testing.T) {
65		tests := []struct {
66			name                          string
67			cursor, offset, visible, want int
68		}{
69			{"inside", 3, 0, 8, 0},
70			{"below window scrolls", 8, 0, 8, 1},
71			{"above window scrolls", 2, 5, 8, 2},
72			{"top does not wrap", 0, 0, 8, 0},
73			{"no highlight keeps offset", -1, 3, 8, 3},
74			{"never negative", 0, -2, 8, 0},
75		}
76		for _, tt := range tests {
77			if got := Window(tt.cursor, tt.offset, tt.visible); got != tt.want {
78				t.Errorf("%s: Window(%d,%d,%d) = %d, want %d", tt.name, tt.cursor, tt.offset, tt.visible, got, tt.want)
79			}
80		}
81	}
82	
83	func TestColumns(t *testing.T) {
84		tests := []struct {
85			width            int
86			alias, desc, nam bool
87		}{
88			{120, true, true, true}, {80, true, true, true}, {60, true, true, true},
89			{54, true, true, true}, {50, true, false, true}, {40, true, false, true},
90			{34, true, false, true}, {30, false, false, true},
91		}
92		for _, tt := range tests {
93			l := Columns(tt.width)
94			if l.Marker != 2 {
95				t.Errorf("w=%d: Marker = %d, want 2", tt.width, l.Marker)
96			}
97			if (l.Name > 0) != tt.nam || (l.Alias > 0) != tt.alias || (l.Desc > 0) != tt.desc {
98				t.Errorf("w=%d: layout %+v, want name=%v alias=%v desc=%v", tt.width, l, tt.nam, tt.alias, tt.desc)
99			}
100			if l.Desc > 0 && l.Desc < 20 {
101				t.Errorf("w=%d: Desc = %d, never below 20", tt.width, l.Desc)
102			}
103			if used := 1 + l.Marker + l.Name + l.Alias + l.Desc; used > tt.width {
104				t.Errorf("w=%d: columns use %d cells", tt.width, used)
105			}
106		}
107		if l := Columns(80); l.Name != 15 || l.Alias != 14 {
108			t.Errorf("w=80: name/alias = %d/%d, want 15/14", l.Name, l.Alias)
109		}
110		if l := Columns(120); l.Name != 18 || l.Alias != 18 {
111			t.Errorf("w=120: name/alias = %d/%d, want 18/18", l.Name, l.Alias)
112		}
113		if l := Columns(30); l.Name > 30-6 {
114			t.Errorf("w=30: Name = %d, want at most W-6", l.Name)
